// ── Orgs / Teams / commit-comments / issue-types serializers ───────────────────────────────
export function toGithubOrg(o: GithubOrg): Record<string, unknown> {
  const api = `https://api.github.com`;
  const id = 0x20000000 + (parseInt(createHash('sha256').update(`org:${o.login}`).digest('hex').slice(0, 8), 16) % 0x0fffffff);
  return {
    login: o.login, id, node_id: null, type: 'Organization',
    description: o.description ?? null, name: o.name ?? null, company: o.company ?? null,
    blog: o.blog ?? null, location: o.location ?? null, email: o.email ?? null,
    url: `${api}/orgs/${o.login}`, repos_url: `${api}/orgs/${o.login}/repos`, hooks_url: `${api}/orgs/${o.login}/hooks`,
    members_url: `${api}/orgs/${o.login}/members{/member}`, html_url: `https://github.com/${o.login}`,
    ...(o.billing_email !== undefined ? { billing_email: o.billing_email ?? null } : {}),
    created_at: o.created_at ?? null, updated_at: o.updated_at ?? null,
  };
}
