// Map a gist to GitHub's gist shape (GET /gists/:id).
export function toGithubGist(g: GithubGist): Record<string, unknown> {
  const api = `https://api.github.com`;
  const files: Record<string, unknown> = {};
  for (const f of g.files) {
    const content = f.content ?? '';
    files[f.filename] = { filename: f.filename, language: f.language ?? null, size: f.size ?? content.length, content, type: 'text/plain', truncated: false };
  }
  const out: Record<string, unknown> = {
    id: g.id,
    description: g.description ?? null,
    public: g.public ?? false,
    files,
    url: `${api}/gists/${g.id}`,
    html_url: `https://gist.github.com/${g.id}`,
    comments: 0,
    owner: null,
    node_id: null,
  };
  if (g.created_at !== undefined) out.created_at = g.created_at;
  if (g.updated_at !== undefined) out.updated_at = g.updated_at;
  return out;
}

