export function toGithubEnvironment(e: GithubEnvironment): Record<string, unknown> {
  const api = `https://api.github.com/repos/${e.repository}`;
  const protection_rules: Array<Record<string, unknown>> = [];
  if (e.wait_timer) protection_rules.push({ id: 1, type: 'wait_timer', wait_timer: e.wait_timer });
  if (e.reviewers?.length) protection_rules.push({ id: 2, type: 'required_reviewers', reviewers: e.reviewers.map((login) => ({ type: 'User', reviewer: { login, type: 'User' } })) });
  return {
    id: actionsId(`${e.repository}:env:${e.name}`),
    node_id: null,
    name: e.name,
    url: `${api}/environments/${encodeURIComponent(e.name)}`,
    html_url: `https://github.com/${e.repository}/deployments/${encodeURIComponent(e.name)}`,
    created_at: e.created_at ?? null,
    updated_at: e.updated_at ?? null,
    protection_rules,
    deployment_branch_policy: null,
  };
}

