      const validReasons = ['false positive', "won't fix", 'used in tests'];
      if (newState === 'dismissed' && !validReasons.includes(String(body.dismissed_reason))) return { response: { status: 422, body: { message: 'Validation Failed', errors: [{ resource: 'CodeScanningAlert', field: 'dismissed_reason', code: 'invalid' }] } } };
      const fields: Record<string, unknown> = { number, repository: repo, state: newState, updated_at: occurredAt };
      if (newState === 'dismissed') { fields.dismissed_reason = String(body.dismissed_reason); fields.dismissed_comment = body.dismissed_comment !== undefined ? String(body.dismissed_comment) : null; fields.dismissed_at = occurredAt; }
      else { fields.dismissed_reason = null; fields.dismissed_comment = null; fields.dismissed_at = null; }
      await applyTwinWrite(SERVICE, { operation: 'code_scanning_alert.update', subjectType: 'code_scanning_alert', subjectId: `csalert:${repo}#${number}`, fields, occurredAt, actor: { kind: 'agent' } }, req.root);
      const a = githubState(req.root).codeScanningAlerts.find((x) => x.repository === repo && x.number === number)!;
