    if (body.build_type !== undefined) fields.build_type = String(body.build_type);
    if (body.https_enforced !== undefined) fields.https_enforced = Boolean(body.https_enforced);
    if (req.method === 'POST') { fields.status = 'building'; if (fields.source_branch === undefined) fields.source_branch = 'main'; if (fields.source_path === undefined) fields.source_path = '/'; }
    await applyTwinWrite(SERVICE, { operation: req.method === 'POST' ? 'pages_site.create' : 'pages_site.update', subjectType: 'pages_site', subjectId: `pages:${repo}`, fields, occurredAt, actor: { kind: 'agent' } }, req.root);
