    await applyTwinWrite(SERVICE, { operation: 'pages_build.create', subjectType: 'pages_build', subjectId: `pagesbuild:${id}`, fields: { repository: repo, status: 'built', commit: createHash('sha256').update(`${repo}:build:${id}`).digest('hex').slice(0, 40), duration: 1000, created_at: occurredAt }, occurredAt, actor: { kind: 'agent' } }, req.root);
